def list_message_ids(run_composio_tool, query):
    out=[]; page=None
    while True:
        args={'user_id':'me','query':query,'max_results':500,'ids_only':True,'include_payload':False,'verbose':False,'include_spam_trash':True}
        if page: args['page_token']=page
        res, err = run_composio_tool('GMAIL_FETCH_EMAILS', args)
        if err: return out, err
        d=(res or {}).get('data') or {}
        for m in (d.get('messages') or []):
            mid=m.get('messageId') or m.get('id')
            if mid: out.append(mid)
        page=d.get('nextPageToken')
        if not page: break
    return out, None
